--- a/src/main/java/com/pulsestream/telemetry/ingestion/infrastructure/R2dbcTelemetryRecordRepository.java
+++ b/src/main/java/com/pulsestream/telemetry/ingestion/infrastructure/R2dbcTelemetryRecordRepository.java
@@ -17,6 +17,11 @@
 import com.pulsestream.telemetry.ingestion.domain.TelemetryRevision;

 public class R2dbcTelemetryRecordRepository implements TelemetryRecordRepository {
+
+    private static final String UNIQUE_VIOLATION_SQL_STATE = "23505";
+    private static final int INITIAL_REVISION_NUMBER = 1;
+    private static final String INITIAL_REVISION_REASON = "INITIAL";
+    private static final String INSERT_RECORD_SQL = "INSERT INTO telemetry_records (device_id, metric, t_device, t_ingress, sample_value, validation_status, payload_hash, payload) VALUES (:deviceId, :metric, :tDevice, :tIngress, :value, :status, :hash, :payload)";

     private final DatabaseClient client;

@@ -41,7 +46,7 @@

     private static boolean isUniqueViolation(Throwable error) {
         for (Throwable t = error; t != null; t = t.getCause()) {
-            if (t instanceof R2dbcException r && "23505".equals(r.getSqlState())) {
+            if (t instanceof R2dbcException r && UNIQUE_VIOLATION_SQL_STATE.equals(r.getSqlState())) {
                 return true;
             }
         }
@@ -64,13 +69,13 @@

     @Override
     public Mono<Boolean> appendRecord(TelemetrySample sample) {
-        String plain = sample.payload();
-        String stored = plain == null ? null : cipher.encrypt(plain);
-        String hash = sha256Hex(plain == null ? "" : plain);
-        TransactionalOperator tx = TransactionalOperator.create(new R2dbcTransactionManager(client.getConnectionFactory()));
-        DatabaseClient.GenericExecuteSpec base = client.sql("INSERT INTO telemetry_records (device_id, metric, t_device, t_ingress, sample_value, validation_status, payload_hash, payload) VALUES (:deviceId, :metric, :tDevice, :tIngress, :value, :status, :hash, :payload)").bind("deviceId", sample.deviceId()).bind("metric", sample.metric()).bind("tDevice", utc(sample.tDevice())).bind("tIngress", utc(sample.tIngress())).bind("value", sample.value()).bind("status", sample.status().name()).bind("hash", hash);
-        DatabaseClient.GenericExecuteSpec spec = stored == null ? base.bindNull("payload", String.class) : base.bind("payload", stored);
-        Mono<Boolean> appended = spec.filter(statement -> statement.returnGeneratedValues("record_id")).map(row -> row.get(0, Long.class)).one().flatMap(recordId -> insertRevision(recordId, 1, sample.value(), "INITIAL")).thenReturn(true);
-        return tx.transactional(appended).onErrorResume(RuntimeException.class, error -> isUniqueViolation(error) ? Mono.just(false) : Mono.error(error));
+        String plainPayload = sample.payload();
+        String encryptedPayload = plainPayload == null ? null : cipher.encrypt(plainPayload);
+        String payloadHash = sha256Hex(plainPayload == null ? "" : plainPayload);
+        TransactionalOperator transaction = TransactionalOperator.create(new R2dbcTransactionManager(client.getConnectionFactory()));
+        DatabaseClient.GenericExecuteSpec insert = client.sql(INSERT_RECORD_SQL).bind("deviceId", sample.deviceId()).bind("metric", sample.metric()).bind("tDevice", utc(sample.tDevice())).bind("tIngress", utc(sample.tIngress())).bind("value", sample.value()).bind("status", sample.status().name()).bind("hash", payloadHash);
+        DatabaseClient.GenericExecuteSpec withPayload = encryptedPayload == null ? insert.bindNull("payload", String.class) : insert.bind("payload", encryptedPayload);
+        Mono<Boolean> appended = withPayload.filter(statement -> statement.returnGeneratedValues("record_id")).map(row -> row.get(0, Long.class)).one().flatMap(recordId -> insertRevision(recordId, INITIAL_REVISION_NUMBER, sample.value(), INITIAL_REVISION_REASON)).thenReturn(true);
+        return transaction.transactional(appended).onErrorResume(RuntimeException.class, error -> isUniqueViolation(error) ? Mono.just(false) : Mono.error(error));
     }
 }
